package dev.mote.remote.ui

import org.junit.Assert.assertEquals
import org.junit.Test

class FlickerTest {
    private fun E(wait: Long, depth: Double, dbl: Boolean) = Flicker.Event(wait, depth, dbl)

    /** Generated by running design/mote-v1/flicker.js's mulberry32 + schedule in node (seed "MOTE"). */
    private val fromJs = listOf(
        E(6380L, 0.17523046820424498, false),
        E(13825L, 0.14578914964804426, true),
        E(12832L, 0.1140125458710827, true),
        E(6565L, 0.15911090639419853, false),
        E(13882L, 0.11800981228007004, true),
        E(11573L, 0.13486810198519378, false),
        E(9955L, 0.19519773093052206, true),
        E(12380L, 0.18675986262969674, false),
        E(12136L, 0.10421761074103415, false),
        E(9227L, 0.10224659265950323, false),
        E(9709L, 0.05904753615614027, false),
        E(10616L, 0.19631991535425186, false),
        E(8294L, 0.18469409754034133, false),
        E(12326L, 0.1908068080898374, false),
        E(8667L, 0.18980751892086117, false),
        E(11492L, 0.0907644311664626, false),
        E(9180L, 0.19378799641272054, true),
        E(5844L, 0.07411779831163585, false),
        E(13398L, 0.16441844360670074, false),
        E(11221L, 0.17988392559345812, true),
    )

    @Test fun scheduleMatchesFlickerJs() {
        val f = Flicker()
        fromJs.forEachIndexed { i, e ->
            val k = f.next()
            assertEquals("wait $i", e.waitMs, k.waitMs)
            assertEquals("depth $i", e.depth, k.depth, 1e-15)
            assertEquals("double $i", e.double, k.double)
        }
    }

    @Test fun sameSeedSameSchedule() {
        val a = Flicker(); val b = Flicker()
        repeat(100) { assertEquals(a.next(), b.next()) }
    }

    @Test fun dipCurveMatchesJs() {
        // node: dip(15, .1), dip(70, .1), dip(30, .06)
        assertEquals(0.925, Flicker.dip(15.0, 0.1), 1e-12)
        assertEquals(0.95, Flicker.dip(70.0, 0.1), 1e-12)
        assertEquals(0.94, Flicker.dip(30.0, 0.06), 1e-12)
        assertEquals(1.0, Flicker.dip(110.0, 0.2), 0.0)
        val dbl = Flicker.Event(5000, 0.1, true)
        assertEquals(1.0, dbl.lum(140.0), 0.0)
        assertEquals(1 - 0.06, dbl.lum(200.0), 1e-12)
        assertEquals(280L, dbl.lengthMs)
        assertEquals(0.92f, Flicker.coreAlpha(0.8f), 1e-6f)
    }
}
